static ssize_t
ucl_msgpack_parse_int(struct ucl_parser *parser,
					  struct ucl_stack *container, size_t len, enum ucl_msgpack_format fmt,
					  const unsigned char *pos, size_t remain)
{
	ucl_object_t *obj;
	int8_t iv8;
	int16_t iv16;
	int32_t iv32;
	int64_t iv64;
	uint16_t uiv16;
	uint32_t uiv32;
	uint64_t uiv64;


	if (len > remain) {
		return -1;
	}

	obj = ucl_msgpack_new_object(parser, UCL_INT);

	if (obj == NULL) {
		return -1;
	}

	switch (fmt) {
	case msgpack_positive_fixint:
		obj->value.iv = (*pos & 0x7f);
		len = 1;
		break;
	case msgpack_negative_fixint:
		obj->value.iv = (int8_t)*pos;
		len = 1;
		break;
	case msgpack_uint8:
		obj->value.iv = (unsigned char) *pos;
		len = 1;
		break;
	case msgpack_int8:
		memcpy(&iv8, pos, sizeof(iv8));
		obj->value.iv = iv8;
		len = 1;
		break;
	case msgpack_int16:
		memcpy(&iv16, pos, sizeof(iv16));
		iv16 = FROM_BE16(iv16);
		obj->value.iv = iv16;
		len = 2;
		break;
	case msgpack_uint16:
		memcpy(&uiv16, pos, sizeof(uiv16));
		uiv16 = FROM_BE16(uiv16);
		obj->value.iv = uiv16;
		len = 2;
		break;
	case msgpack_int32:
		memcpy(&iv32, pos, sizeof(iv32));
		iv32 = FROM_BE32(iv32);
		obj->value.iv = iv32;
		len = 4;
		break;
	case msgpack_uint32:
		memcpy(&uiv32, pos, sizeof(uiv32));
		uiv32 = FROM_BE32(uiv32);
		obj->value.iv = uiv32;
		len = 4;
		break;
	case msgpack_int64:
		memcpy(&iv64, pos, sizeof(iv64));
		iv64 = FROM_BE64(iv64);
		obj->value.iv = iv64;
		len = 8;
		break;
	case msgpack_uint64:
		memcpy(&uiv64, pos, sizeof(uiv64));
		uiv64 = FROM_BE64(uiv64);

		if (uiv64 > (uint64_t) INT64_MAX) {
			/*
			 * ucl keeps integers as int64, and wrapping the value round to a
			 * negative number is worse than refusing to read it
			 */
			ucl_create_err(&parser->err,
						   "msgpack integer does not fit into int64: %ju",
						   (uintmax_t) uiv64);
			ucl_object_unref(obj);

			return -1;
		}

		obj->value.iv = (int64_t) uiv64;
		len = 8;
		break;
	default:
		assert(0);
		break;
	}

	parser->cur_obj = obj;

	return len;
}
